def is_balanced(sequence):
    stack = []
    for num in sequence:
        if num > 0:
            stack.append(num)
        else:
            if stack and stack[-1] == -num:
                stack.pop()
            else:
                return False
    return not stack

def main():
    n = int(input())
    cards = [tuple(map(int, input().split())) for _ in range(2 * n)]

    front_numbers = []
    back_numbers = []

    for card in cards:
        front_numbers.append(card[0])
        back_numbers.append(card[1])

    if is_balanced(front_numbers) and is_balanced(back_numbers):
        print("YES")
        for card in cards:
            print(card[0], card[1])
    else:
        print("NO")

if __name__ == "__main__":
    main()
